# NY Metropolitan Zone bounds — Morristown (W), Hartford (N), Montauk (E), New Brunswick (S)
MORRISTOWN_LON = -74.482
DANBURY_LAT = 41.395
MONTAUK_LON = -71.955
NEW_BRUNSWICK_LAT = 40.486
NEW_LONDON_LON = -72.100
NEW_LONDON_LAT = 41.356
HARTFORD_LAT = 41.764
# Northern grid edge: extended past Danbury to Hartford so all of Connecticut south of
# Hartford (Fairfield, New Haven, and the Hartford area) fits on the map.
METRO_NORTH_LAT = 41.80


def get_nyc_matched_cell_degrees() -> tuple[float, float]:
    """Degrees per grid cell — identical to the OSM NYC map (50×50 over active NYC bounds)."""
    from nyc_city_data import get_nyc_bounds
    b = get_nyc_bounds()
    cell_lat = (b['max_lat'] - b['min_lat']) / b['height']
    cell_lon = (b['max_lon'] - b['min_lon']) / b['width']
    return cell_lat, cell_lon


def get_ny_metro_grid_origin() -> tuple[float, float]:
    """Southwest grid origin aligned with the NYC map for 1:1 cell spacing."""
    from nyc_city_data import get_nyc_bounds
    nyc = get_nyc_bounds()
    return nyc['min_lat'], MORRISTOWN_LON


def compute_ny_metro_grid_dimensions() -> tuple[int, int]:
    """Grid size from geographic span and NYC-matched cell size."""
    cell_lat, cell_lon = get_nyc_matched_cell_degrees()
    origin_lat, origin_lon = get_ny_metro_grid_origin()
    width = int(round((MONTAUK_LON - origin_lon) / cell_lon))
    height = int(round((METRO_NORTH_LAT - origin_lat) / cell_lat))
    return max(50, width), max(50, height)


_METRO_GRID_W, _METRO_GRID_H = compute_ny_metro_grid_dimensions()
_GRID_ORIGIN_LAT, _GRID_ORIGIN_LON = get_ny_metro_grid_origin()

