def get_station_name_for_point(x: float, y: float, game_map, current_year: int = None, line_name: str = None, existing_names: set = None) -> str:
    """Return a human-friendly station name for (x,y) on the NY Metro map.
    Prefers nearby road names (OSM); falls back to a generic name. Intended for AI station naming."""
    try:
        year = int(current_year) if current_year is not None else getattr(game_map, "start_year", 1830) or 1830
    except Exception:
        year = 1830
    existing_names = existing_names or set()

    # Cross-streets ("Canal St & Broadway") or the neighbourhood; older logic below is the fallback.
    try:
        from geo_naming import station_name_for_point
        geo = station_name_for_point(game_map, x, y, year, existing_names)
        if geo:
            return geo
    except Exception:
        pass

    road_name = ""
    try:
        from map_presets_nyc_road_utils import get_nearest_road_name_for_point, format_osm_road_name_for_display
        from game_presets import AI_STATION_STREET_NAME_MAX_DISTANCE_GRID
        road_name = get_nearest_road_name_for_point(
            game_map, x, y, year, bounds=get_ny_metro_bounds(), tolerance_grid=2.0, max_segments=120,
            max_distance_grid=AI_STATION_STREET_NAME_MAX_DISTANCE_GRID,
        )
    except Exception:
        road_name = ""

    name = format_osm_road_name_for_display(road_name)
    if not name:
        name = "Station"

    if name not in existing_names:
        return name
    k = 2
    while f"{name} ({k})" in existing_names and k < 999:
        k += 1
    return f"{name} ({k})"


def get_excluded_water_points() -> set:
    """Get grid points that are always water. NY Metro uses road-based detection; no fixed excluded set."""
    return set()


def is_point_on_road_at_year(x: float, y: float, current_year: int, game_map) -> bool:
    """Check if grid point is on a road at current_year. Used by map_preset_loader."""
    from map_presets_nyc_road_utils import is_point_on_road_at_year as _impl
    return _impl(x, y, current_year, game_map, bounds=get_ny_metro_bounds())


def is_point_on_bridge_at_year(x: float, y: float, current_year: int, game_map) -> bool:
    """Check if grid point is on a bridge at current_year. Used by map_preset_loader."""
    from map_presets_nyc_road_utils import is_point_on_bridge_at_year as _impl
    return _impl(x, y, current_year, game_map, bounds=get_ny_metro_bounds())


def polyline_follows_streets_for_ai(game_map, points: list, current_year: int) -> bool:
    from map_presets_nyc_road_utils import _polyline_land_segments_on_street
    return _polyline_land_segments_on_street(game_map, list(points or []), current_year)


def is_ny_metro_map(map_center_lat: float = None, map_center_lon: float = None, width: int = None, height: int = None) -> bool:
    """Check if map parameters match NY Metropolitan Zone map.
    
    Args:
        map_center_lat: Map center latitude
        map_center_lon: Map center longitude
        width: Map width
        height: Map height
        
    Returns:
        True if parameters match NY Metropolitan Zone map
    """
    if map_center_lat is None or map_center_lon is None:
        return False
    
    # Check if center is within NY Metro bounds
    bounds = get_ny_metro_bounds()
    if not (bounds['min_lat'] <= map_center_lat <= bounds['max_lat']):
        return False
    if not (bounds['min_lon'] <= map_center_lon <= bounds['max_lon']):
        return False
    
    # Check if dimensions match (approximately)
    if width is not None and height is not None:
        bw, bh = bounds['width'], bounds['height']
        if abs(width - bw) > max(25, bw * 0.12) or abs(height - bh) > max(25, bh * 0.12):
            return False
    
    return True

def get_nyc_to_metro_grid_offset() -> tuple[int, int]:
    """Integer offset so NYC grid (nx, ny) maps to metro (offset_x + nx, offset_y + ny) without rounding loss."""
    from nyc_city_data import get_nyc_bounds
    nyc_bounds = get_nyc_bounds()
    cell_lat, cell_lon = get_nyc_matched_cell_degrees()
    origin_lat, origin_lon = get_ny_metro_grid_origin()
    offset_x = round((nyc_bounds['min_lon'] - origin_lon) / cell_lon)
    offset_y = round((nyc_bounds['min_lat'] - origin_lat) / cell_lat)
    return offset_x, offset_y


def nyc_grid_to_metro_grid(nx: int, ny: int) -> tuple[int, int]:
    """Map one NYC OSM grid cell to the corresponding NY Metro grid cell (1:1, no lat/lon rounding)."""
    offset_x, offset_y = get_nyc_to_metro_grid_offset()
    return offset_x + int(nx), offset_y + int(ny)


def get_nyc_derived_metro_cells(width: int = None, height: int = None) -> set[tuple[int, int]]:
    """Metro grid cells for every NYC_INITIAL_POPULATION cell (same layout as the NYC OSM map).

    Used by tests and the population generator only; reads the NYC map's population table from
    its file (without importing it) and returns nothing when that map is absent.
    """
    import os
    from map_preset_utils import read_initial_population_from_file

    nyc_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'map_presets_nyc.py')
    nyc_population = (read_initial_population_from_file(nyc_file, 'NYC_INITIAL_POPULATION')
                      if os.path.exists(nyc_file) else {})
    cells: set[tuple[int, int]] = set()
    for x, y in nyc_population:
        cells.add(nyc_grid_to_metro_grid(x, y))
    return cells


def _grid_to_latlon(x: int, y: int, bounds: dict, width: int, height: int) -> tuple[float, float]:
    cell_lat, cell_lon = get_nyc_matched_cell_degrees()
    origin_lat, origin_lon = get_ny_metro_grid_origin()
    lat = origin_lat + y * cell_lat
    lon = origin_lon + x * cell_lon
    return lat, lon


def _latlon_to_grid(lat: float, lon: float, bounds: dict, width: int, height: int) -> tuple[int, int]:
    cell_lat, cell_lon = get_nyc_matched_cell_degrees()
    origin_lat, origin_lon = get_ny_metro_grid_origin()
    x = round((lon - origin_lon) / cell_lon)
    y = round((lat - origin_lat) / cell_lat)
    return max(0, min(width, x)), max(0, min(height, y))


def _is_in_nyc_bounds(lat: float, lon: float) -> bool:
    from nyc_city_data import get_nyc_bounds
    b = get_nyc_bounds()
    return b['min_lat'] <= lat <= b['max_lat'] and b['min_lon'] <= lon <= b['max_lon']


def is_county_open_water(lat: float, lon: float) -> bool:
    """Bays and ocean inside county polygons — not the Hudson River (handled via OSM relation)."""
    for area in COUNTY_OPEN_WATER_AREAS:
        if (
            area['min_lat'] <= lat <= area['max_lat']
            and area['min_lon'] <= lon <= area['max_lon']
        ):
            return True
    return False


def is_metro_water_location(lat: float, lon: float) -> bool:
    """True when (lat, lon) is open water on the NY Metro map (Hudson, LIS, bays)."""
    for exempt in METRO_MAINLAND_WATER_EXEMPT:
        if (
            exempt['min_lat'] <= lat <= exempt['max_lat']
            and exempt['min_lon'] <= lon <= exempt['max_lon']
        ):
            return False
    for area in METRO_WATER_AREAS:
        if (
            area['min_lat'] <= lat <= area['max_lat']
            and area['min_lon'] <= lon <= area['max_lon']
        ):
            return True
    return False


def get_ferry_segment_points_for_ai(game_map, current_year: int, max_points: int = 12, existing_line_routes=None, rng=None) -> list:
    """Ferry route candidates over this map's harbours, rivers and sounds (for AI ferry companies)."""
    from map_preset_utils import ai_ferry_segment_candidates
    return ai_ferry_segment_candidates('ny_metro', get_ny_metro_bounds(), game_map, max_points=max_points, rng=rng)


def is_water_location(lat: float, lon: float, osm_integration=None) -> bool:
    """Water detection for NY Metro (used by map_preset_loader and point builders).

    Uses the OSM coastline / lake data (get_water_mask). The NYC map's own test must not be
    used here: it reports New Jersey and other non-NYC land as excluded, which on this map
    made every station site around Newark and Jersey City look like water. The rough
    METRO_WATER_AREAS rectangles are only a fallback when the data file is missing.
    """
    try:
        mask = get_water_mask()
        if mask.has_data():
            return mask.is_water_latlon(lat, lon)
    except Exception:
        pass
    return is_metro_water_location(lat, lon)


